import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const SIZES = ["S", "M", "L"];

function App() {
  const [selected, setSelected] = useState("M");
  return (
    <View style={styles.row}>
      {SIZES.map((s) => (
        <Pressable key={s} testID="size" onPress={() => setSelected(s)}
          style={styles.size}>
          {/* энд бичнэ үү: сонгогдсон бол styles.active-г нэм */}
          <Text style={styles.text}>{s}</Text>
        </Pressable>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flex: 1, flexDirection: "row", gap: 12, padding: 24, alignItems: "center", justifyContent: "center" },
  size: { width: 56, height: 56, borderRadius: 12, borderWidth: 1, borderColor: "#cbd5e1", alignItems: "center", justifyContent: "center" },
  active: { backgroundColor: "#2563eb", borderColor: "#2563eb" },
  text: { fontSize: 18, fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const SIZES = ["S", "M", "L"];

function App() {
  const [selected, setSelected] = useState("M");
  return (
    <View style={styles.row}>
      {SIZES.map((s) => (
        <Pressable key={s} testID="size" onPress={() => setSelected(s)}
          style={[styles.size, selected === s && styles.active]}>
          <Text style={styles.text}>{s}</Text>
        </Pressable>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flex: 1, flexDirection: "row", gap: 12, padding: 24, alignItems: "center", justifyContent: "center" },
  size: { width: 56, height: 56, borderRadius: 12, borderWidth: 1, borderColor: "#cbd5e1", alignItems: "center", justifyContent: "center" },
  active: { backgroundColor: "#2563eb", borderColor: "#2563eb" },
  text: { fontSize: 18, fontWeight: "bold" },
});

registerRootComponent(App);
